CREATE TABLE music_track_association (id UUID PRIMARY KEY DEFAULT uuid_v7(), owner_id UUID NOT NULL, track_id UUID NOT NULL, candidate_id UUID NOT NULL, artist_id UUID NOT NULL, album_id UUID NOT NULL, edition_id UUID NOT NULL, disc_id UUID NOT NULL, membership_id UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(track_id) REFERENCES music_track(id), FOREIGN KEY(candidate_id) REFERENCES music_metadata_candidate(id), FOREIGN KEY(artist_id) REFERENCES music_artist(id), FOREIGN KEY(album_id) REFERENCES music_album(id), FOREIGN KEY(edition_id) REFERENCES music_edition(id), FOREIGN KEY(disc_id) REFERENCES music_disc(id), FOREIGN KEY(membership_id) REFERENCES music_track_membership(id), UNIQUE(owner_id,track_id,candidate_id));
